import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import os, subprocess, tempfile, stat
T = tempfile.mkdtemp(); B = os.path.join(T, 'bin'); os.makedirs(B); log = os.path.join(T, 'claude.log')
sh = os.path.join(B, 'claude'); open(sh, 'w').write('#!/bin/sh\necho "$@" >> ' + log + '\necho {}\n'); os.chmod(sh, 0o755)
env = {k: v for k, v in os.environ.items() if not k.startswith('KB_COORD')}
env.update(PATH=B + os.pathsep + env['PATH'], KB_COORD_STORE=os.path.join(T, 'c.sqlite'), CLAUDE_PLUGIN_DATA=T, NO_COLOR='1')
def rem(alert):
    if os.path.exists(log): os.remove(log)
    p = subprocess.run([sys.executable, '_tools/kbask.py', 'remediate', alert], capture_output=True, text=True, env=env, timeout=180)
    import time; time.sleep(3)
    return p, os.path.exists(log)
p, called = rem('sessions.orphan')
print('orphan:', p.returncode, called, (p.stdout + p.stderr)[-300:])
assert not called, 'kbask remediate started a model session for an orphan alert, whose remedy is fixed'
lst = subprocess.run([sys.executable, '_tools/coord.py', 'list'], capture_output=True, text=True, env=env, timeout=60).stdout
assert 'answer/' in lst, 'no coord answer was posted for the orphan alert: ' + lst[-300:]
